      </g>

      <g id="dotLayer" class="dots"></g>

      <!-- ===== hit layer ===== -->
      <g id="hitLayer">
        <rect class="part-hit" data-part="B1" x="98" y="82" width="112" height="46"/>
        <rect class="part-hit" data-part="B1" x="100" y="80" width="100" height="16" data-net="vcc"/>
        <rect class="part-hit" data-part="B1" x="118" y="88" width="66" height="14" data-net="MINUS"/>
        <rect class="part-hit" id="swHit" x="248" y="150" width="140" height="132" data-part="S1"/>
        <rect class="part-hit" data-part="D1" x="428" y="180" width="96" height="74"/>
        <rect class="part-hit" data-part="R1" x="610" y="194" width="112" height="54"/>
