    </svg>

    <div class="status-chip" id="statusChip">Switch open — LED off</div>
    <div class="probe-badge" id="probeBadge" hidden>
      <span id="probeText"></span>
      <button id="probeClose" aria-label="Close probe">×</button>
    </div>
    <div class="tooltip" id="tooltip" hidden></div>
    <div class="hint">Hover a part for its current and voltage · click a wire to probe its net · click the switch to toggle it</div>
  </section>

  <!-- ================= side panel ================= -->
  <aside class="side">

    <div class="card mistakes" id="mistakesCard">
      <div class="card-head">
        <h2>Mistakes found</h2>
        <span class="pill" id="mistakePill">2 in sketch</span>
      </div>
      <ol id="mistakeList"></ol>
    </div>

    <div class="card" id="burntCard" hidden>
      <div class="card-head"><h2>Burnt out</h2></div>
      <p>D1 exceeded its 30 mA maximum and is now open-circuit — no current flows anywhere in the loop. Replace the part to restore the circuit.</p>
      <button id="replaceLed">Replace LED</button>
    </div>

    <div class="card controls">
      <div class="card-head"><h2>Controls</h2></div>

      <div class="ctl">
        <div class="ctl-row"><label for="battSlider">Battery voltage · B1</label><output id="battVal">5.0 V</output></div>
        <input type="range" id="battSlider" min="1" max="12" step="0.1" value="5">
      </div>

      <div class="ctl">
        <div class="ctl-row"><label for="r1Slider">Series resistor · R1</label><output id="r1Val">200 Ω</output></div>
        <input type="range" id="r1Slider" min="10" max="1000" step="5" value="200">
      </div>

      <label class="check"><input type="checkbox" id="switchToggle"> S1 closed</label>

      <p class="warn-note" id="overNote" hidden>D1 is above its 20 mA rating — raise R1 or lower B1</p>
      <p class="note">D1 — Vf 2.0 V (unknown colour) · rated 20 mA · burns out above 30 mA. LED current at 5 V and 200 Ω is about 14–15 mA. Wire resistance of a closed switch is 0.001 Ω; battery internal resistance is 0.2 Ω.</p>
    </div>

    <div class="card readings">
      <div class="card-head"><h2>Live readings</h2></div>
      <table aria-label="Part readings">
        <thead><tr><th>Part</th><th>Voltage</th><th>Current</th></tr></thead>
        <tbody id="readBody"></tbody>
      </table>
    </div>

  </aside>
</main>

<script>
'use strict';
/* =========================================================
   5 V switched LED — interactive simulation of a sketch
   Device models:
     battery : ideal source + 0.2 Ω internal resistance
     led     : off until Vf, then I = (V - Vf) / 10 Ω (Vf = 2 V, unknown colour)
     switch  : 0.001 Ω closed, open otherwise
     resistor: ohmic
   ========================================================= */

const $  = s => document.querySelector(s);
const $$ = s => Array.from(document.querySelectorAll(s));
const SVGNS = 'http://www.w3.org/2000/svg';
const VF = 2.0;                 // LED forward voltage, unknown colour
const LED_RATED = 0.020;        // 20 mA
const LED_BURN  = 0.030;        // 30 mA
const R_INT = 0.2, R_SW = 0.001;

const stateInfo = {
  mode: 'fixed',                // start in "Fixed"
  switchClosed: false,
  batteryV: 5,
  r1: 200,
  burnt: false,
  probeNet: null,
  lastCurrent: 0,
  lastRes: null
};

const fmtI = I => {
  const a = Math.abs(I);
  if (a < 5e-7) return '0.00 mA';
  if (a < 1e-3) return (I*1e6).toFixed(1) + ' µA';
  return (I*1000).toFixed(a < 0.01 ? 2 : 1) + ' mA';
};
const fmtV = v => (v < -0.0005 ? '-' : '') + Math.abs(v).toFixed(2) + ' V';
const fmtR = r => r >= 1000 ? (r/1000).toFixed(2).replace(/\.?0+$/,'') + ' kΩ' : Math.round(r) + ' Ω';
const clamp01 = v => Math.max(0, Math.min(1, v));
const lerp = (a,b,t) => a + (b-a)*t;
const mixRGB = (c1,c2,t) => `rgb(${Math.round(lerp(c1[0],c2[0],t))},${Math.round(lerp(c1[1],c2[1],t))},${Math.round(lerp(c1[2],c2[2],t))})`;

/* ---------- circuit definition ---------- */
function getComponents(mode){
  const emf = stateInfo.batteryV, r1 = stateInfo.r1, closed = stateInfo.switchClosed;
  if (mode === 'fixed') return [
    {id:'B1', type:'battery', nodes:['vcc','gnd'],  value:emf},
    {id:'S1', type:'switch',  nodes:['vcc','nled'], closed},
    {id:'D1', type:'led',     nodes:['nled','nres']},
    {id:'R1', type:'resistor',nodes:['nres','gnd'], value:r1},
    {id:'G1', type:'ground',  nodes:['gnd']},
    {id:'G2', type:'ground',  nodes:['gnd']}
  ];
  // as drawn: battery minus floats; S1 drawn as changeover with grounded lower throw
  return [
    {id:'B1', type:'battery', nodes:['vcc','bminus'], value:emf},
    {id:'S1', type:'switch',  nodes:['vcc','gnd','nled'], closed},
    {id:'D1', type:'led',     nodes:['nled','nres']},
    {id:'R1', type:'resistor',nodes:['nres','gnd'], value:r1},
    {id:'G1', type:'ground',  nodes:['gnd']},
    {id:'G2', type:'ground',  nodes:['gnd']}
  ];
}

/* ---------- nodal solver (Gaussian elimination, tiny matrix) ---------- */
function gauss(A, b){
  const n = b.length;
  const M = A.map((row,i) => Array.from(row).concat(b[i]));
  for (let col = 0; col < n; col++){
    let piv = col;
    for (let r = col+1; r < n; r++) if (Math.abs(M[r][col]) > Math.abs(M[piv][col])) piv = r;
    const tmp = M[col]; M[col] = M[piv]; M[piv] = tmp;
    const d = M[col][col] || 1e-12;
    for (let r = 0; r < n; r++){
      if (r === col) continue;
      const f = M[r][col] / d;
      if (f === 0) continue;
      for (let c = col; c <= n; c++) M[r][c] -= f * M[col][c];
    }
  }
  const x = new Float64Array(n);
  for (let i = 0; i < n; i++) x[i] = M[i][n] / (M[i][i] || 1e-12);
  return x;
}

function solveOnce(burnt){
  const comps = getComponents(stateInfo.mode);
  const ref = 'gnd';
  const nodeSet = new Set();
  comps.forEach(c => c.nodes.forEach(n => { if (n !== ref) nodeSet.add(n); }));
  const nodes = Array.from(nodeSet);
  const idx = {}; nodes.forEach((n,i) => idx[n] = i);
  const N = nodes.length;

  let V = new Float64Array(N);
  const Vn = n => { const i = idx[n]; return i === undefined ? 0 : V[i]; };

  const led = comps.find(c => c.id === 'D1');
  let ledG = 1e-9;

  for (let iter = 0; iter < 80; iter++){
    const A = Array.from({length:N}, () => new Float64Array(N));
    const b = new Float64Array(N);
    for (let i = 0; i < N; i++) A[i][i] += 1e-9;      // gmin against floating singularities

    const sG = (a, c, g) => {
      const ia = idx[a], ib = idx[c];
      if (ia !== undefined) A[ia][ia] += g;
      if (ib !== undefined) A[ib][ib] += g;
      if (ia !== undefined && ib !== undefined){ A[ia][ib] -= g; A[ib][ia] -= g; }
    };
    const sI = (a, c, I) => {
      const ia = idx[a], ib = idx[c];
      if (ia !== undefined) b[ia] += I;
      if (ib !== undefined) b[ib] -= I;
    };

    for (const c of comps){
      switch (c.type){
        case 'battery': {
          const g = 1 / R_INT;
          sG(c.nodes[0], c.nodes[1], g);
          sI(c.nodes[0], c.nodes[1], g * c.value);
          break;
        }
        case 'resistor': case 'lamp': {
          const R = c.value || (c.type === 'lamp' ? 20 : 1000);
          sG(c.nodes[0], c.nodes[1], 1 / R);
          break;
        }
        case 'switch': {
          if (c.closed){
            const g = 1 / R_SW;
            if (c.nodes.length === 2) sG(c.nodes[0], c.nodes[1], g);
            else sG(c.nodes[0], c.nodes[2], g);       // wiper to upper throw
          }
          break;
        }
        case 'led': {
          if (!burnt){
            if (ledG > 1e-8){ sG(c.nodes[0], c.nodes[1], ledG); sI(c.nodes[0], c.nodes[1], ledG * VF); }
            else sG(c.nodes[0], c.nodes[1], 1e-9);
          }
          break;
        }
        case 'diode': {
          if (ledG > 1e-8){ sG(c.nodes[0], c.nodes[1], ledG); sI(c.nodes[0], c.nodes[1], ledG * 0.7); }
          else sG(c.nodes[0], c.nodes[1], 1e-9);
          break;
        }
        case 'capacitor': break;                       // open at DC
        case 'potentiometer': {
          const p = clamp01(c.position ?? 0.5), R = c.value || 10000;
          const n = c.nodes;                           // [a, wiper, b]
          sG(n[0], n[1], 1 / Math.max(1, R * p));
          sG(n[1], n[2], 1 / Math.max(1, R * (1 - p)));
          break;
        }
      }
    }

    V = gauss(A, b);

    // update LED companion model
    if (burnt) break;
    const vak = Vn(led.nodes[0]) - Vn(led.nodes[1]);
    const newG = vak > VF ? 1 / 10 : 1e-9;
    if (Math.abs(newG - ledG) < 1e-12){ ledG = newG; break; }
    ledG = newG;
  }

  const volts = {};
  comps.forEach(c => c.nodes.forEach(n => { volts[n] = Vn(n); }));
  volts['gnd'] = 0;

  const parts = {};
  for (const c of comps){
    if (c.type === 'battery'){
      const p = Vn(c.nodes[0]), m = Vn(c.nodes[1]);
      parts[c.id] = { current: c.value / R_INT - (p - m) / R_INT, voltage: p - m };   // current delivered out of plus
    } else if (c.type === 'resistor' || c.type === 'lamp'){
      const R = c.value || (c.type === 'lamp' ? 20 : 1000);
      const p = Vn(c.nodes[0]), m = Vn(c.nodes[1]);
      parts[c.id] = { current: (p - m) / R, voltage: p - m };
    } else if (c.type === 'switch'){
      if (c.nodes.length === 2){
        const a = Vn(c.nodes[0]), b2 = Vn(c.nodes[1]);
        parts[c.id] = { current: c.closed ? (a - b2) / R_SW : 0, voltage: a - b2, on: !!c.closed };
      } else {
        const a = Vn(c.nodes[0]), w = Vn(c.nodes[2]);
        parts[c.id] = { current: c.closed ? (a - w) / R_SW : 0, voltage: a - w, on: !!c.closed };
      }
    } else if (c.type === 'led'){
      const a = Vn(c.nodes[0]), k = Vn(c.nodes[1]);
      const v = a - k;
      const I = burnt ? 0 : (v > VF ? (v - VF) / 10 : 0);
      parts[c.id] = { current: I, voltage: v, brightness: clamp01(I / LED_RATED), on: I > 1e-6, burnt };
    } else if (c.type === 'diode'){
      const a = Vn(c.nodes[0]), k = Vn(c.nodes[1]);
      const v = a - k;
      const I = burnt ? 0 : (v > 0.7 ? (v - 0.7) / 0.5 : 0);
      parts[c.id] = { current: I, voltage: v, on: I > 1e-6 };
    } else if (c.type === 'ground'){
      parts[c.id] = { current: 0, voltage: 0 };
    } else if (c.type === 'capacitor'){
      parts[c.id] = { current: 0, voltage: Vn(c.nodes[0]) - Vn(c.nodes[1]) };
    }
  }
  return { volts, parts };
}

function solveAll(){
  let res = solveOnce(stateInfo.burnt);
  if (!stateInfo.burnt && res.parts.D1.current > LED_BURN){
    stateInfo.burnt = true;                 // latch burnout, re-solve as open-circuit
    res = solveOnce(true);
  }
  stateInfo.lastRes = res;
  stateInfo.lastCurrent = res.parts.D1 ? res.parts.D1.current : 0;
  return res;
}

/* ---------- wire layout per mode ---------- */
function wiresFor(mode){
  const w = [];
  if (mode === 'fixed'){
    w.push({net:'gnd', pts:[[150,96],[150,44],[52,44],[52,300],[168,300]]});   // B1- to G1 via left side
    w.push({net:'vcc', pts:[[150,110],[150,220],[296,220]]});
  } else {
    w.push({net:'vcc',    pts:[[150,110],[150,174],[296,174]]});
    w.push({net:'bminus', pts:[[150,84],[150,96]]});                           // floating stub
    w.push({net:'gnd',    pts:[[296,258],[250,258],[250,300],[168,300]]});     // grounded lower throw
  }
  w.push({net:'nled', pts:[[352,220],[452,220]]});
  w.push({net:'nres', pts:[[540,220],[620,220]]});
  w.push({net:'gnd',  pts:[[712,220],[858,220],[858,262]]});
  return w;
}

const wireLayer = $('#wireLayer');
const hitLayerExtra = [];

function buildWires(){
  wireLayer.innerHTML = '';
  hitLayerExtra.length = 0;
  for (const w of wiresFor(stateInfo.mode)){
    const pl = document.createElementNS(SVGNS, 'polyline');
    pl.setAttribute('points', w.pts.map(p => p.join(',')).join(' '));
    pl.setAttribute('class', 'wire');
    pl.setAttribute('data-net', w.net);
    wireLayer.appendChild(pl);
    // fat invisible hit target for probing
    const hit = document.createElementNS(SVGNS, 'polyline');
    hit.setAttribute('points', w.pts.map(p => p.join(',')).join(' '));
    hit.setAttribute('class', 'hitwire');
    hit.setAttribute('data-net', w.net);
    wireLayer.appendChild(hit);
    hitLayerExtra.push(hit);
  }
}

/* ---------- current dots along the loop ---------- */
const PATH_A = [[150,110],[150,220],[296,220],[352,220],[452,220],[540,220],[620,220],[712,220],[858,220],[858,258]];
const PATH_B = [[168,300],[52,300],[52,44],[150,44],[150,96]];
const dotLayer = $('#dotLayer');
const dotPool = [];
for (let i = 0; i < 34; i++){
  const c = document.createElementNS(SVGNS, 'circle');
  c.setAttribute('r', '3.6'); c.setAttribute('opacity', '0');
  dotLayer.appendChild(c); dotPool.push(c);
}
const pathLenCache = new Map();
function pathLen(p){
  const k = p.map(q => q.join(',')).join('|');
  if (pathLenCache.has(k)) return pathLenCache.get(k);
  let L = 0; for (let i = 1; i < p.length; i++) L += Math.hypot(p[i][0]-p[i-1][0], p[i][1]-p[i-1][1]);
  pathLenCache.set(k, L); return L;
}
function pointAt(p, d){
  let acc = 0;
  for (let i = 1; i < p.length; i++){
    const dx = p[i][0]-p[i-1][0], dy = p[i][1]-p[i-1][1];
    const seg = Math.hypot(dx, dy);
    if (acc + seg >= d){
      const t = seg === 0 ? 0 : (d - acc) / seg;
      return [p[i-1][0] + dx*t, p[i-1][1] + dy*t];
    }
    acc += seg;
  }
  return p[p.length-1];
}
let dotOffset = 0, lastT = 0;
function tick(t){
  requestAnimationFrame(tick);
  const dt = lastT ? Math.min(0.05, (t - lastT) / 1000) : 0;
  lastT = t;
  const I = stateInfo.lastCurrent;
  const visible = stateInfo.mode === 'fixed' && I > 5e-4 && !stateInfo.burnt;
  const spd = 26 + 2400 * I;
  if (visible) dotOffset = (dotOffset + spd * dt) % 100000;
  let k = 0;
  if (visible){
    for (const path of [PATH_A, PATH_B]){
      const L = pathLen(path), n = Math.floor(L / 78);
      for (let i = 0; i < n; i++){
        if (k >= dotPool.length) break;
        const d = (dotOffset + i * 78) % L;
        const p = pointAt(path, d);
        const c = dotPool[k++];
        c.setAttribute('cx', p[0].toFixed(1));
        c.setAttribute('cy', p[1].toFixed(1));
        c.setAttribute('opacity', '1');
      }
    }
  }
  for (; k < dotPool.length; k++) dotPool[k].setAttribute('opacity', '0');
}

