      if (p.on !== undefined) out.on = p.on;
      if (p.brightness !== undefined) out.brightness = p.brightness;
      if (p.burnt !== undefined) out.burnt = p.burnt;
      parts[id] = out;
    }
    return { mode: stateInfo.mode, nodes: Object.assign({}, res.volts), parts };
